#!/usr/bin/env node
// scrub — remove Claude attribution from a GitHub issue, PR, comment or review body (O09, K006).
//
//   node .harness/tools/scrub.mjs            in Actions (harness-scrub.yml): reads the event, re-reads
//                                            the body it names, and saves it back only if scrubbing changed it;
//                                            then sweeps every body posted or edited since the last good run
//   node .harness/tools/scrub.mjs --stdin    prints the scrubbed text of stdin (tests, local use)
//
// What goes: a footer line "Generated by/with Claude Code", a Co-authored-by line for
// noreply@anthropic.com, a Claude-Session line, and every claude.ai link (a Markdown link loses its
// text too, a link ending a line the separator before it); a line left with no words, and a `---`
// rule left dangling at the end, go with them. Code blocks, inline code and HTML attribute values are
// left alone, so a body can still quote these strings on purpose. Everything else is unchanged.
//
// Safe on untrusted input: the body is only data to a few linear regexes, no code is checked out
// from the event, and the edit is made with GITHUB_TOKEN, whose events start no workflow (no loop).
//
// One run per burst (K059): the workflow keeps one run going and one waiting for the whole repository,
// and GitHub drops an older waiting run when a newer one arrives. So each run also sweeps: every issue,
// pull request, comment and review comment updated since the newest earlier run that finished green
// (less a margin), and the reviews of the pull requests among them. A dropped run's body is therefore
// cleaned by the run that replaced it, and thirty comments in a burst cost one or two runs, not thirty.

import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { ghClient, ghPages } from './lib.mjs';

// Line-level: only a footer- or trailer-shaped line goes, never a sentence that merely mentions it.
const GENERATED = /^[ \t]*(?:[^\w\s]{1,4}[ \t]{0,4})?[_*]{0,2}[ \t]{0,4}generated[ \t]{1,4}(?:by|with)[ \t]{1,4}\[?claude[ \t_-]{0,2}code\b/i;
const TRAILER = /^[ \t]*(?:co-authored-by:[^\n]{0,200}noreply@anthropic\.com|claude-session:[ \t]{0,4}https?:\/\/)/i;
// claude.ai and its subdomains only; bounded quantifiers keep every scan linear (no ReDoS)
const HOST = String.raw`https?:\/\/(?:[a-z0-9-]{1,63}\.){0,4}claude\.ai(?![\w-]|\.\w)(?:[/?#][^\s)>\]"'<]{0,2000})?`;
// a link at the end of a line takes the separator before it: "by X · [thread](…)_" → "by X_"
const TAIL = new RegExp(String.raw`[ \t]{0,20}(?:[·•,:–—-][ \t]{0,20})?(?:\[[^\]\n]{0,500}\]\([ \t]{0,4}<?${HOST}>?[ \t]{0,4}\)|<?${HOST}>?)(?=[_*]{0,3}[ \t]{0,20}$)`, 'gi');
// elsewhere a link goes with one space before it, and with parentheses that held only it
const MID = new RegExp(String.raw`(?:[ \t]?\[[^\]\n]{0,500}\]\([ \t]{0,4}<?${HOST}>?[ \t]{0,4}\)|[ \t]?\([ \t]{0,4}<?${HOST}>?[ \t]{0,4}\)|[ \t]?<?${HOST}>?)`, 'gi');

/** Remove claude.ai links from one line, leaving inline code spans and HTML attribute values alone. */
function unlink(line) {
  return line.split(/(`+[^`]*`+)/).map((part, i) => {
    if (i % 2) return part; // an inline code span
    // an attribute value (href="…", src='…') is markup, not a link to strip
    return part.replace(TAIL, (m, off, all) => (/=[ \t]*["']?$/.test(all.slice(0, off)) ? m : ''))
      .replace(MID, (m, off, all) => (/=[ \t]*["']?$/.test(all.slice(0, off + (m[0] === ' ' || m[0] === '\t' ? 1 : 0))) ? m : ''));
  }).join('');
}

/** The text without Claude attribution. Returns the input unchanged when there is none. */
export function scrub(text) {
  if (typeof text !== 'string' || !text) return text;
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  const out = [];
  let fence = null, removed = false;
  for (const line of text.split(/\r?\n/)) {
    const f = line.match(/^[ \t]{0,3}(`{3,}|~{3,})/);
    if (fence) { out.push(line); if (f && f[1][0] === fence[0] && f[1].length >= fence.length) fence = null; continue; }
    if (f) { fence = f[1]; out.push(line); continue; }
    if (GENERATED.test(line) || TRAILER.test(line)) { removed = true; continue; }
    const l = /claude\.ai/i.test(line) ? unlink(line) : line;
    if (l !== line) {
      removed = true;
      if (!/[\p{L}\p{N}]/u.test(l)) continue; // nothing but the link was on the line
    }
    out.push(l);
  }
  if (!removed) return text;
  while (out.length && out.at(-1).trim() === '') out.pop();
  if (out.length && /^[ \t]*(-{3,}|\*{3,}|_{3,})[ \t]*$/.test(out.at(-1))) { out.pop(); while (out.length && out.at(-1).trim() === '') out.pop(); }
  return out.join(eol).replace(/(\r?\n){3,}/g, `${eol}${eol}`) + (/\r?\n$/.test(text) && out.length ? eol : '');
}

/**
 * The footer or trailer lines a body still carries (outside code blocks), as the scrubber would remove
 * them: "Generated by/with Claude Code", a Claude co-author or session line. Links are not counted here.
 * Used by guard.mjs `pr-body`, the merge gate (K044).
 */
export function footerLines(text) {
  if (typeof text !== 'string' || !text) return [];
  const found = [];
  let fence = null;
  for (const line of text.split(/\r?\n/)) {
    const f = line.match(/^[ \t]{0,3}(`{3,}|~{3,})/);
    if (fence) { if (f && f[1][0] === fence[0] && f[1].length >= fence.length) fence = null; continue; }
    if (f) { fence = f[1]; continue; }
    if (GENERATED.test(line) || TRAILER.test(line)) found.push(line.trim());
  }
  return found;
}

// --- GitHub Actions entry point -------------------------------------------------------------------------
/** The REST path of the body an event names, and how to save it. */
export function target(name, p) {
  const repo = p.repository?.full_name;
  if (!repo) return null;
  if (name === 'issues' && p.issue) return { path: `/repos/${repo}/issues/${p.issue.number}`, method: 'PATCH' };
  if ((name === 'pull_request_target' || name === 'pull_request') && p.pull_request) return { path: `/repos/${repo}/pulls/${p.pull_request.number}`, method: 'PATCH' };
  if (name === 'issue_comment' && p.comment) return { path: `/repos/${repo}/issues/comments/${p.comment.id}`, method: 'PATCH' };
  if (name === 'pull_request_review_comment' && p.comment) return { path: `/repos/${repo}/pulls/comments/${p.comment.id}`, method: 'PATCH' };
  if (name === 'pull_request_review' && p.review && p.pull_request) return { path: `/repos/${repo}/pulls/${p.pull_request.number}/reviews/${p.review.id}`, method: 'PUT' };
  return null;
}

// the workflow's own token (GITHUB_TOKEN), never a session's GH_TOKEN
const api = ghClient('harness-kit-scrub', { token: () => process.env.GITHUB_TOKEN });

/** Workflows whose failed run on a PR's head the scrubber starts again after it removes a footer (K044). */
export const RERUN = new Set(['harness-guard', 'hands-check', 'check']);
/** The failed runs of `runs` (a GitHub run list) that the scrubber re-runs. */
export const rerunnable = (runs) => (runs || []).filter((r) => r && r.conclusion === 'failure' && RERUN.has(r.name)).map((r) => r.id);

/**
 * The scrubber's own edit starts no workflow, so a required check that failed on the footer (harness-guard
 * waits 90 s for the scrubber, which may be queued behind it on a single runner) would stay red on a clean
 * body. Start those failed runs again. Best effort: a read-only token, or any error, only warns.
 */
async function rerunChecks(repo, sha, get = api) {
  try {
    const l = await get('GET', `/repos/${repo}/actions/runs?head_sha=${encodeURIComponent(sha)}&per_page=50`);
    for (const id of rerunnable(l.workflow_runs)) await get('POST', `/repos/${repo}/actions/runs/${id}/rerun-failed-jobs`);
  } catch (e) { console.log(`::warning::scrub: could not start the failed checks again (${e.message.slice(0, 120)})`); }
}

async function main() {
  if (process.argv.includes('--stdin')) { process.stdout.write(scrub(readFileSync(0, 'utf8'))); return; }
  const name = process.env.GITHUB_EVENT_NAME;
  const t = target(name, JSON.parse(readFileSync(process.env.GITHUB_EVENT_PATH, 'utf8')));
  if (!t) { console.log(`scrub: nothing to scrub on ${name}`); return; }
  if (!process.env.GITHUB_TOKEN) throw new Error('GITHUB_TOKEN is not set');
  await event(name, t);
  // a fork's or Dependabot's event has a read-only token and a group of its own: it sweeps nothing
  if (process.env.SCRUB_SWEEP !== 'off') await sweepRun();
}

async function event(name, t) {
  // re-read: the event's copy may be older than a later edit, which must not be overwritten
  const now = await api('GET', t.path);
  const clean = scrub(now.body);
  if (clean === now.body) { console.log(`scrub: ${t.path}: no attribution`); return; }
  try {
    await api(t.method, t.path, { body: clean });
  } catch (e) {
    // a fork's or Dependabot's PR events get a read-only token: say so on the run, do not turn it red
    if (e.status === 403 && process.env.GITHUB_EVENT_NAME?.startsWith('pull_request')) { console.log(`::warning::scrub: ${t.path}: attribution left; this event's token is read-only (${e.message})`); return; }
    throw e;
  }
  console.log(`scrub: ${t.path}: attribution removed`);
  if (name === 'pull_request') await rerunChecks(JSON.parse(readFileSync(process.env.GITHUB_EVENT_PATH, 'utf8')).repository.full_name, now.head.sha);
}

// --- the sweep: one run cleans everything a dropped waiting run would have (K059) -----------------------
export const SWEEP_MARGIN_MS = 5 * 60 * 1000;      // overlap with the last good run: an event a little older than its start
export const SWEEP_FALLBACK_MS = 24 * 3600 * 1000;  // no good run found (first run, unreadable list): the last day, never more
export const SWEEP_PAGES = 30;                      // 100 items a page, per listing: room for a full day on a busy repository
export const SWEEP_REVIEW_PRS = 30;                 // pull requests whose reviews are read

/**
 * Where this run's sweep starts: the creation of the newest earlier run of the same workflow that finished
 * green in this repository's own group, less the margin; never further back than the fallback. A run from
 * a fork's pull request (its own group, read-only token) or a cancelled, skipped or failed run covered
 * nothing, so it does not count.
 */
export function sweepSince(runs, { repo, currentId, now, notBefore }) {
  const floor = now - SWEEP_FALLBACK_MS;
  // a run older than the workflow file's last change ran an older file, which may not have swept (0.53.1):
  // it covered only its own event, so it never anchors the window; an unknown change date trusts no run
  const since = notBefore === undefined ? -Infinity : Date.parse(notBefore);
  const good = (runs || []).filter((r) => r && Number(r.id) < Number(currentId) && r.conclusion === 'success'
    && Date.parse(r.created_at) >= since
    && !(String(r.event || '').startsWith('pull_request') && r.head_repository?.full_name !== repo)
    && r.actor?.login !== 'dependabot[bot]' && Number.isFinite(Date.parse(r.created_at)));
  if (!good.length) return new Date(floor).toISOString();
  const last = Math.max(...good.map((r) => Date.parse(r.created_at)));
  return new Date(Math.max(floor, last - SWEEP_MARGIN_MS)).toISOString();
}

/** Every item of a paged listing, at most SWEEP_PAGES pages; `capped` says a page limit was met. */
async function pages(path, get = api) {
  const { items, cut } = await ghPages(get, path, { max: SWEEP_PAGES });
  return { items, capped: cut };
}

/**
 * Scrub every body updated since `since`. `get` is the API call (injected by the tests). Returns the paths
 * it saved. A body is re-read just before it is saved, so a later edit is never overwritten; a read-only
 * token (403) leaves that body with a warning and the sweep goes on.
 */
export async function sweep(repo, since, get = api) {
  const saved = [];
  const fix = async (path, method, listed, pr) => {
    if (scrub(listed) === listed) return;
    let now;
    try {
      now = await get('GET', path);
      const clean = scrub(now.body);
      if (clean === now.body) return;
      await get(method, path, { body: clean });
    } catch (e) {
      if (e.status === 403) { console.log(`::warning::scrub: ${path}: attribution left; the token is read-only here`); return; }
      if (e.status === 404 || e.status === 410) { console.log(`::warning::scrub: ${path}: gone since it was listed`); return; }
      throw e;
    }
    saved.push(path);
    console.log(`scrub: ${path}: attribution removed (sweep)`);
    if (pr) { try { await rerunChecks(repo, (await get('GET', `/repos/${repo}/pulls/${pr}`)).head.sha, get); } catch { /* best effort */ } }
  };
  const q = `since=${encodeURIComponent(since)}&sort=updated&direction=asc`;
  const issues = await pages(`/repos/${repo}/issues?state=all&${q}`, get);
  const comments = await pages(`/repos/${repo}/issues/comments?${q}`, get);
  const reviewComments = await pages(`/repos/${repo}/pulls/comments?${q}`, get);
  const capped = [issues, comments, reviewComments].some((l) => l.capped);
  for (const i of issues.items) await fix(`/repos/${repo}/issues/${i.number}`, 'PATCH', i.body, i.pull_request ? i.number : null);
  for (const c of comments.items) await fix(`/repos/${repo}/issues/comments/${c.id}`, 'PATCH', c.body);
  for (const c of reviewComments.items) await fix(`/repos/${repo}/pulls/comments/${c.id}`, 'PATCH', c.body);
  for (const p of issues.items.filter((i) => i.pull_request).slice(-SWEEP_REVIEW_PRS)) {
    const reviews = await get('GET', `/repos/${repo}/pulls/${p.number}/reviews?per_page=100`);
    for (const r of reviews || []) await fix(`/repos/${repo}/pulls/${p.number}/reviews/${r.id}`, 'PUT', r.body);
  }
  // a cut listing leaves bodies behind: the run fails, so the next one sweeps from the last green run again
  if (capped) { const e = new Error(`more than ${SWEEP_PAGES * 100} items in one listing since ${since}; the next run sweeps them`); e.capped = true; e.saved = saved; throw e; }
  return saved;
}

/** The run's sweep in Actions: window from this workflow's own run list, then the sweep. */
async function sweepRun() {
  const repo = process.env.GITHUB_REPOSITORY;
  const file = String(process.env.GITHUB_WORKFLOW_REF || '').replace(/@.*$/, '').split('/').pop();
  if (!repo || !process.env.GITHUB_RUN_ID) return;
  let runs = [];
  if (file) {
    try { runs = (await api('GET', `/repos/${repo}/actions/workflows/${encodeURIComponent(file)}/runs?per_page=100`)).workflow_runs; }
    catch (e) { console.log(`::warning::scrub: could not read this workflow's runs (${e.message.slice(0, 120)}); sweeping the last day`); }
  }
  // when this workflow file last changed: runs before it ran another file (a kit update), so they anchor nothing
  let notBefore = null;
  if (file) {
    try { notBefore = (await api('GET', `/repos/${repo}/commits?path=${encodeURIComponent(`.github/workflows/${file}`)}&per_page=1`))[0]?.commit?.committer?.date ?? null; }
    catch (e) { console.log(`::warning::scrub: could not read when this workflow last changed (${e.message.slice(0, 120)}); sweeping the last day`); }
  }
  const since = sweepSince(runs, { repo, currentId: process.env.GITHUB_RUN_ID, now: Date.now(), notBefore: notBefore ?? new Date(8.64e15).toISOString() });
  const saved = await sweep(repo, since);
  console.log(`scrub: sweep since ${since}: ${saved.length} bod${saved.length === 1 ? 'y' : 'ies'} cleaned`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  main().catch((e) => { console.error(`scrub: ${e.message}`); process.exit(1); });
}
